function isrStarts(lengths, raises, isrCost) {
  // lengths[i] = cycles of instruction i; raises = sorted interrupt arrival times; after each instruction serve every interrupt that has arrived
  var t = 0, next = 0, starts = [];
  for (var i = 0; i < lengths.length; i++) {
    t += lengths[i];
    while (next < raises.length && raises[next] <= t) {
      starts.push(t);
      t += isrCost;
      next++;
    }
  }
  return { starts: starts, finish: t };
}
